def walk(obj, depth=0):
    ind='  '*depth
    if isinstance(obj, dict):
        mc=obj.get('model_class','')
        name=obj.get('name')
        typ=obj.get('type')
        label=obj.get('label')
        value=obj.get('value')
        opts=obj.get('options')
        print(f\"{ind}{mc or typ} name={name"'!r} type={typ!r} label={label!r} value={value!r}")
        if opts:
            print(f"{ind} options={opts}")
        if '"'test_param' in obj:
            print(f\"{ind} test_param:\")
            walk(obj['test_param'], depth+1)
        if 'cases' in obj:
            for c in obj['cases']:
                print(f\"{ind} WHEN value={c.get('value')"'!r}")
                for inp in c.get('"'inputs',[]): walk(inp, depth+1)
        if 'inputs' in obj and 'cases' not in obj:
            for inp in obj['inputs']: walk(inp, depth+1)
    elif isinstance(obj, list):
        for x in obj: walk(x, depth)

walk(t['inputs'])
